#include "d2d_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

static void d2d_exception_get_data (UInt8 data_count) ;

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void d2d_exception_gwr_enc (void)
{
	d2d_exception_get_data (1) ;
}

//--------------------------------------------------------------------------//

void d2d_exception_read_eeprom (void)
{
	d2d_exception_get_data (1) ;
}

//--------------------------------------------------------------------------//

void d2d_exception_write_eeprom (void)
{
	d2d_exception_get_data (2) ;
}

//--------------------------------------------------------------------------//
static void d2d_exception_get_data (UInt8 data_count)
{
	UInt8 i ;

	for(i = 0 ; i < data_count ; i++) 
    {
	  SInt16 arg_data = get_d2d_cmd (D2D_GET_TIMEOUT);

	  if(arg_data < 0)
	    {
		  d2d_err_add(D2D_ERR_TIMEOUT) ;
		  return ;
		}
    }	
}


